import{bV as n,aL as a,u as p,G as e}from"./chunks/framework.DvBUyM1S.js";const u=JSON.parse('{"title":"CSS 实现多行文本“展开收起”","description":"","frontmatter":{"title":"CSS 实现多行文本“展开收起”","date":"2022-03-16T16:35:52.000Z","permalink":"/pages/5aae97/","categories":["前端开发","CSS"],"tags":[null]},"headers":[],"relativePath":"02.开发/04.CSS/03.CSS 实现多行文本“展开收起”.md","filePath":"02.开发/04.CSS/03.CSS 实现多行文本“展开收起”.md","lastUpdated":1652078909000}'),l={name:"02.开发/04.CSS/03.CSS 实现多行文本“展开收起”.md"};function i(t,s,r,c,b,o){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="css-实现多行文本-展开收起" tabindex="-1">CSS 实现多行文本“展开收起” <a class="header-anchor" href="#css-实现多行文本-展开收起" aria-label="Permalink to &quot;CSS 实现多行文本“展开收起”&quot;">​</a></h1><blockquote><p>来源<a href="https://juejin.cn/post/6963904955262435336#heading-5" target="_blank" rel="noreferrer">https://juejin.cn/post/6963904955262435336#heading-5</a></p></blockquote><h1 id="css-实现多行文本-展开收起-1" tabindex="-1">CSS 实现多行文本“展开收起” <a class="header-anchor" href="#css-实现多行文本-展开收起-1" aria-label="Permalink to &quot;CSS 实现多行文本“展开收起”&quot;">​</a></h1><p>多行文本展开收起是一个很常见的交互， 如下图演示</p><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/a63ede2531304998a343e09862def4da~tplv-k3u1fbpfcp-watermark.image" alt="展开3 (1).gif" loading="lazy"> 实现这一类布局和交互难点主要有以下几点</p><ul><li>位于多行文本右下角的“展开收起”按钮</li><li>“展开”和“收起”两种状态的切换</li><li>当文本不超过指定行数时，不显示“展开收起”按钮</li></ul><p>说实话，之前单独看这个布局，即使借助 JavaScript 也不是一件容易的事啊（需要计算文字宽度动态截取文本，<a href="https://link.juejin.cn/?target=https%3A%2F%2Fjustineo.github.io%2Fvue-clamp%2Fdemo%2F%3Flang%3Dzh%26fileGuid%3DXtpJhGpvWxj6qcTr" title="https://justineo.github.io/vue-clamp/demo/?lang=zh&amp;fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">vue-clamp</a>就是这么做的），更别说下面的交互和判断逻辑了，不过经过我的一番琢磨，其实纯 CSS 也能完美实现的，下面就一步一步来看看如何实现吧~</p><h1 id="一、位于右下角的-展开收起-按钮" tabindex="-1">一、位于右下角的“展开收起”按钮 <a class="header-anchor" href="#一、位于右下角的-展开收起-按钮" aria-label="Permalink to &quot;一、位于右下角的“展开收起”按钮&quot;">​</a></h1><p>很多设计同学都喜欢这样的设计，把按钮放在右下角，和文本 <strong>混合</strong> 在一起，而不是单独一行，视觉上可能更加舒适美观。先看看多行文本截断吧，这个比较简单</p><h2 id="_1-多行文本截断" tabindex="-1">1. 多行文本截断 <a class="header-anchor" href="#_1-多行文本截断" aria-label="Permalink to &quot;1\\. 多行文本截断&quot;">​</a></h2><p>假设有这样一个 html 结构</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;div class=&quot;text&quot;&gt;</span></span>
<span class="line"><span>  浮动元素是如何定位的</span></span>
<span class="line"><span>正如我们前面提到的那样，当一个元素浮动之后，它会被移出正常的文档流，然后向左或者向右平移，一直平移直到碰到了所处的容器的边框，或者碰到另外一个浮动的元素。</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>多行文本超出省略大家应该很熟悉这个了吧，主要用到用到 <strong>line-clamp</strong>，关键样式如下</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text {</span></span>
<span class="line"><span>  display: -webkit-box;</span></span>
<span class="line"><span>  -webkit-line-clamp: 3;</span></span>
<span class="line"><span>  -webkit-box-orient: vertical;</span></span>
<span class="line"><span>  overflow: hidden;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/6a5696e759e64b7b8047ae290d26c151~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><h2 id="_2-右下角环绕效果" tabindex="-1">2. 右下角环绕效果 <a class="header-anchor" href="#_2-右下角环绕效果" aria-label="Permalink to &quot;2\\. 右下角环绕效果&quot;">​</a></h2><p>提到 <strong>文本环绕效果</strong>，一般能想到 <strong>浮动 float</strong>，没错，千万不要以为浮动已经是过去式了，具体的场景还是很有用的。比如下面放一个按钮，然后设置浮动</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;div class=&quot;text&quot;&gt;</span></span>
<span class="line"><span>  &lt;button class=&quot;btn&quot;&gt;展开&lt;/button&gt;</span></span>
<span class="line"><span>  浮动元素是如何定位的</span></span>
<span class="line"><span>正如我们前面提到的那样，当一个元素浮动之后，它会被移出正常的文档流，然后向左或者向右平移，一直平移直到碰到了所处的容器的边框，或者碰到另外一个浮动的元素。</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.btn {</span></span>
<span class="line"><span>  float: left;</span></span>
<span class="line"><span>  /*其他装饰样式*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/81910f3cb59b4e7bb436767380b9e6f3~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"> 如果设置右浮动</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.btn {</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  /*其他装饰样式*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/d54a4a9036b442a5919207b333a99802~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"> 这时已经有了 <strong>环绕</strong> 的效果了，只是位于右上角，如何将按钮移到右下角呢？先尝试一下 <strong>margin</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.btn {</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  margin-top: 50px;</span></span>
<span class="line"><span>  /*其他装饰样式*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/08a681a28c9b4699b28bd8e3c0180ad2~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>可以看到，虽然按钮到了右下角，但是文本却没有环绕按钮上方的空间，空出了一大截，无能为力了吗？</p><p>虽然 <strong>margin</strong> 不能解决问题，但是整个文本还是受到了浮动按钮的影响，如果有多个浮动元素会怎么样呢？这里用伪元素来 <strong>::before</strong> 代替</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::before{</span></span>
<span class="line"><span>  content: &#39;&#39;;</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  width: 10px;</span></span>
<span class="line"><span>  height: 50px;/*先随便设置一个高度*/</span></span>
<span class="line"><span>  background: red</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/d38fbd24c5c44183bbe5b8bbc4877e02~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>现在按钮到了伪元素的左侧，如何移到下面呢？很简单，清除一下浮动 <strong>clear: both;</strong> 就可以了</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.btn {</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  clear: both;</span></span>
<span class="line"><span>  /*其他装饰样式*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/ed183c8a5b04407fa4a5c924aafe5420~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>可以看到，现在文本是完全环绕在右侧的两个浮动元素了，只要把红色背景的伪元素宽度设置为0（或者不设置宽度，默认就是 0），就实现了右下角环绕的效果</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::before{</span></span>
<span class="line"><span>  content: &#39;&#39;;</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  width: 0; /*设置为0，或者不设置宽度*/</span></span>
<span class="line"><span>  height: 50px;/*先随便设置一个高度*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/26ccbbe9ef8346cc91ac10f01e7ed7d9~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><h2 id="_3-动态高度" tabindex="-1">3. 动态高度 <a class="header-anchor" href="#_3-动态高度" aria-label="Permalink to &quot;3\\. 动态高度&quot;">​</a></h2><p>上面虽然完成了右下加环绕，但是高度是固定的，如何动态设置呢？这里可以用到 <strong>calc</strong> 计算，用整个容器高度减去按钮的高度即可，如下</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::before{</span></span>
<span class="line"><span>  content: &#39;&#39;;</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  width: 0;</span></span>
<span class="line"><span>  height: calc(100% - 24px);</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/8d01e6f976a44f24bd42512b1d37d237~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>很可惜，好像并没有什么效果，打开控制台看看，结果发现 <strong>calc(100% - 24px)</strong> 计算高度为 0</p><p><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/a7363f91c56c4212b2c07bcbe9979f3d~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>原因其实很容易想到，就是<strong>高度 100% 失效</strong>的问题，关于这类问题网上的分析有很多，通常的解决方式是给父级指定一个高度，但是这里的高度是动态变化的，而且还有展开状态，高度更是不可预知，所以设置高度不可取。</p><p>除此之外，其实还有另一种方式，那就是利用 <strong>flex 布局</strong>。大概的方法就是在 <strong>flex 布局</strong> 的子项中，可以通过百分比来计算变化高度，具体可参考 w3.org 中关于 <a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.w3.org%2FTR%2Fcss-flexbox-1%2F%23algo-stretch%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://www.w3.org/TR/css-flexbox-1/#algo-stretch?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">css-flexbox</a> 的描述</p><blockquote><p>If the flex item has<strong>align-self: stretch</strong>, redo layout for its contents, treating this used size as its definite cross size so that percentage-sized children can be resolved.</p></blockquote><p>因此，这里需要给 <strong>.text</strong> 包裹一层，然后设置 <strong>display: flex</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;div class=&quot;wrap&quot;&gt;</span></span>
<span class="line"><span>  &lt;div class=&quot;text&quot;&gt;</span></span>
<span class="line"><span>    &lt;button class=&quot;btn&quot;&gt;展开&lt;/button&gt;</span></span>
<span class="line"><span>    浮动元素是如何定位的</span></span>
<span class="line"><span>  正如我们前面提到的那样，当一个元素浮动之后，它会被移出正常的文档流，然后向左或者向右平移，一直平移直到碰到了所处的容器的边框，或者碰到另外一个浮动的元素。</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.wrap{</span></span>
<span class="line"><span>  display: flex;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>实践下来，display: grid 和 display: -webkit-box 同样有效，原理类似</p></blockquote><p>这样下来，刚才的计算高度就生效了，改变文本的行数，同样位于右下角~</p><p><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/935f53864d20482e93be3672bb7816c5~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>除此之外，动态高度也可以采用负的 margin 来实现（性能会比 calc 略好一点）</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::before{</span></span>
<span class="line"><span>  content: &#39;&#39;;</span></span>
<span class="line"><span>  float: right;</span></span>
<span class="line"><span>  width: 0;</span></span>
<span class="line"><span>  /*height: calc(100% - 24px);*/</span></span>
<span class="line"><span>  height: 100%;</span></span>
<span class="line"><span>  margin-bottom: -24px;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>到这里，右下角环绕的效果就基本完成，省略号也是位于展开按钮之前的，完整代码可以查看 <a href="https://link.juejin.cn/?target=https%3A%2F%2Fcodepen.io%2Fxboxyan%2Fpen%2FExWaBJO%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://codepen.io/xboxyan/pen/ExWaBJO?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">codepen 右下角多行展开环绕效果</a></p><h2 id="_4-其他浏览器的兼容处理" tabindex="-1">4.其他浏览器的兼容处理 <a class="header-anchor" href="#_4-其他浏览器的兼容处理" aria-label="Permalink to &quot;4.其他浏览器的兼容处理&quot;">​</a></h2><p>上面的实现是最完美的处理方式。原本以为兼容性没什么大问题的，毕竟只用到了文本截断和浮动，<strong>-webkit-line-clamp</strong> 虽然是 <strong>-webkit-</strong> 前缀，不过 <strong>firefox</strong> 也是支持的，打开一看傻了眼，<strong>safari</strong> 和 <strong>firefox</strong> 居然全乱了！</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/2cb436e672874d1a8122551440585054~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>这就有点难受了，前面那么多努力都白费了吗？不可能不管这两个，不然就只能是 demo 了，无法用于生产环境。</p><p>赶紧打开控制台看看是什么原因。一番查找，结果发现是<strong>display: -webkit-box</strong>！设置该属性后，原本的文本好像变成了一整块，浮动元素也无法产生环绕效果，去掉之后浮动就正常了</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/3eac0f2ed52b47179e4c13e2d0182bb6~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>那么问题来了：<strong>没有 display: -webkit-box 怎么实现多行截断呢 ？</strong></p><p>其实上面的努力已经实现了右下角环绕的效果，如果在知道行数的情况下设置一个最大高度，是不是也完成了多行截断呢？为了便于设置高度，可以添加一个<strong>行高 line-height</strong>，如果需要设置成 3 行，那高度就设置成<strong>line-height * 3</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text {</span></span>
<span class="line"><span>  /*</span></span>
<span class="line"><span>  display: -webkit-box;</span></span>
<span class="line"><span>  -webkit-line-clamp: 3;</span></span>
<span class="line"><span>  -webkit-box-orient: vertical;</span></span>
<span class="line"><span>  */</span></span>
<span class="line"><span>  line-height: 1.5;</span></span>
<span class="line"><span>  max-height: 4.5em;</span></span>
<span class="line"><span>  overflow: hidden;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>为了方便更好的控制行数，这里可以把常用的行数通过属性选择器独立出来（通常不会太多），如下</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[line-clamp=&quot;1&quot;] {</span></span>
<span class="line"><span>  max-height: 1.5em;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>[line-clamp=&quot;2&quot;] {</span></span>
<span class="line"><span>  max-height: 3em;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>[line-clamp=&quot;3&quot;] {</span></span>
<span class="line"><span>  max-height: 4.5em;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!--3行--&gt;</span></span>
<span class="line"><span>&lt;div class=&quot;text&quot; line-clamp=&quot;3&quot;&gt;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>&lt;/div&gt;</span></span>
<span class="line"><span>&lt;!--5行--&gt;</span></span>
<span class="line"><span>&lt;div class=&quot;text&quot; line-clamp=&quot;5&quot;&gt;</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/02bd8523e51849fb95e630d1040b68b4~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>可以看到基本上正常了，除了没有省略号，现在加上省略号吧，跟在展开按钮之前就可以了，可以用伪元素实现</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.btn::before{</span></span>
<span class="line"><span>  content: &#39;...&#39;;</span></span>
<span class="line"><span>  position: absolute;</span></span>
<span class="line"><span>  left: -10px;</span></span>
<span class="line"><span>  color: #333;</span></span>
<span class="line"><span>  transform: translateX(-100%)</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/c232fa03480b49c4b74ed2d546701696~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>这样，<strong>Safari</strong> 和 <strong>Firefox</strong> 的兼容布局基本上就完成了，完整代码可以查看 <a href="https://link.juejin.cn/?target=https%3A%2F%2Fcodepen.io%2Fxboxyan%2Fpen%2FdyvYNxr%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://codepen.io/xboxyan/pen/dyvYNxr?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">codepen 右下角多行展开环绕效果（全兼容）</a></p><h1 id="二、-展开-和-收起-两种状态" tabindex="-1">二、“展开”和“收起”两种状态 <a class="header-anchor" href="#二、-展开-和-收起-两种状态" aria-label="Permalink to &quot;二、“展开”和“收起”两种状态&quot;">​</a></h1><p>提到 CSS 状态切换，大家都能想到 <strong>input type=&quot;checkbox&quot;</strong> 吧。这里我们也需要用到这个特性，首先加一个 <strong>input</strong>，然后把之前的 <strong>button</strong> 换成 <strong>label</strong> ，并且通过 <strong>for</strong> 属性关联起来</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;div class=&quot;wrap&quot;&gt;</span></span>
<span class="line"><span>  &lt;input type=&quot;checkbox&quot; id=&quot;exp&quot;&gt;</span></span>
<span class="line"><span>  &lt;div class=&quot;text&quot;&gt;</span></span>
<span class="line"><span>    &lt;label class=&quot;btn&quot; for=&quot;exp&quot;&gt;展开&lt;/label&gt;</span></span>
<span class="line"><span>    浮动元素是如何定位的</span></span>
<span class="line"><span>  正如我们前面提到的那样，当一个元素浮动之后，它会被移出正常的文档流，然后向左或者向右平移，一直平移直到碰到了所处的容器的边框，或者碰到另外一个浮动的元素。</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这样，在点击 <strong>label</strong> 的时候，实际上是点击了 <strong>input</strong> 元素，现在来添加两种状态，分别是只显示 3 行和不做行数限制</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.exp:checked+.text{</span></span>
<span class="line"><span>  -webkit-line-clamp: 999; /*设置一个足够大的行数就可以了*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>兼容版本可以直接设置最大高度 <strong>max-height</strong> 为一个较大的值，或者直接设置为 <strong>none</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.exp:checked+.text{</span></span>
<span class="line"><span>  max-height: none;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/c6b26dae80274954a549bbb3d16e6b94~tplv-k3u1fbpfcp-watermark.image" alt="展开2.gif" loading="lazy"></p><p>这里还有一个小问题，“展开”按钮在点击后应该变成“收起”，如何修改呢？</p><p>有一个技巧，凡是碰到需要动态修改内容的，都可以使用伪类 <strong>content</strong> 生成技术，具体做法就是去除或者隐藏按钮里面的文字，采用伪元素生成</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;label class=&quot;btn&quot; for=&quot;exp&quot;&gt;&lt;/label&gt;&lt;!--去除按钮文字--&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.btn::after{</span></span>
<span class="line"><span>  content:&#39;展开&#39; /*采用content生成*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>添加 <strong>:checked</strong> 状态</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.exp:checked+.text .btn::after{</span></span>
<span class="line"><span>  content:&#39;收起&#39;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>兼容版本由于前面的省略号是模拟出来的，不能自动隐藏，所以需要额外来处理</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.exp:checked+.text .btn::before {</span></span>
<span class="line"><span>    visibility: hidden; /*在展开状态下隐藏省略号*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/a4a74035e2c947569da447dd6e2db1ba~tplv-k3u1fbpfcp-watermark.image" alt="展开3.gif" loading="lazy"></p><p>基本和本文开头的效果一致了，完整代码可以查看 <a href="https://link.juejin.cn/?target=https%3A%2F%2Fcodepen.io%2Fxboxyan%2Fpen%2FXWMbJeQ%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://codepen.io/xboxyan/pen/XWMbJeQ?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">codepen 多行展开收起交互</a>，兼容版本可以查看 <a href="https://link.juejin.cn/?target=https%3A%2F%2Fcodepen.io%2Fxboxyan%2Fpen%2FOJpypmR%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://codepen.io/xboxyan/pen/OJpypmR?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">codepen 多行展开收起交互（全兼容）</a></p><p>还有一点，如果给<strong>max-height</strong>设置一个合适的值，注意，<strong>是合适的值</strong>，具体原理可以参考 <a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fchokcoco%2FiCSS%2Fissues%2F91%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://github.com/chokcoco/iCSS/issues/91?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">CSS 奇技淫巧：动态高度过渡动画</a>，还能加上过渡动画</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text{</span></span>
<span class="line"><span>  transition: .3s max-height;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>.exp:checked+.text{</span></span>
<span class="line"><span>  max-height: 200px; /*超出最大行高度就可以了*/</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/e30c3083e02f49dea679909790532f94~tplv-k3u1fbpfcp-watermark.image" alt="Kapture 2021-05-11 at 14.21.55.gif" loading="lazy"></p><h1 id="三、文本行数的判断" tabindex="-1">三、文本行数的判断 <a class="header-anchor" href="#三、文本行数的判断" aria-label="Permalink to &quot;三、文本行数的判断&quot;">​</a></h1><p>上面的交互已经基本满足要求了，但是还是会有问题。比如<strong>当文本较少时</strong>，此时是没有发生截断，也就是没有省略号的，但是“展开”按钮却仍然位于右下角，如何隐藏呢？</p><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/b260271076dd419d98fa0a7f7f1128f6~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>通常 js 的解决方式很容易，比较一下元素的 <strong>scrollHeight</strong> 和 <strong>clientHeight</strong> 即可，然后添加相对应的类名。下面是伪代码</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (el.scrollHeight &gt; el.clientHeight) {</span></span>
<span class="line"><span>  // 文本超出了</span></span>
<span class="line"><span>  el.classList.add(&#39;trunk&#39;)</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>那么，CSS 如何实现这类判断呢？</p><p>可以肯定的是，CSS 是没有这类逻辑判断，大多数我们都需要从别的角度，采用 <strong>“障眼法”</strong> 来实现。比如在这个场景，当没有发生截断的时候，表示文本完全可见了，这时，如果在<strong>文本末尾</strong>添加一个元素（红色小方块），为了不影响原有布局，这里设置了绝对定位</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::after {</span></span>
<span class="line"><span>    content: &#39;&#39;;</span></span>
<span class="line"><span>    width: 10px;</span></span>
<span class="line"><span>    height: 10px;</span></span>
<span class="line"><span>    position: absolute;</span></span>
<span class="line"><span>    background: red;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/3385c2fd19ff47f4bbda9c862c85d485~tplv-k3u1fbpfcp-watermark.image" alt="展开4.gif" loading="lazy"> 可以看到，这里的红色小方块是完全跟随省略号的。当省略号出现时，红色小方块必定消失，<strong>因为已经被挤下去了</strong>，这里把父级 <strong>overflow: hidden</strong> 暂时隐藏就能看到是什么原理了</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/a751b6babca840bf94f4f93e1ee5c853~tplv-k3u1fbpfcp-watermark.image" alt="展开5.gif" loading="lazy"></p><p>然后，可以把刚才这个红色的小方块设置一个<strong>足够大的尺寸</strong>，比如 <strong>100% * 100%</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::after {</span></span>
<span class="line"><span>    content: &#39;&#39;;</span></span>
<span class="line"><span>    width: 100%;</span></span>
<span class="line"><span>    height: 100%;</span></span>
<span class="line"><span>    position: absolute;</span></span>
<span class="line"><span>    background: red;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/73f7b5f1f32e462db7967e8580f2b51e~tplv-k3u1fbpfcp-watermark.image" alt="9202761e575d8627136547a61fc60edc.gif" loading="lazy"></p><p>可以看到，红色的块块把右下角的都覆盖了，现在把背景改为白色（和父级同底色），父级 <strong>overflow: hidden</strong>重新加上</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text::after {</span></span>
<span class="line"><span>    content: &#39;&#39;;</span></span>
<span class="line"><span>    width: 100%;</span></span>
<span class="line"><span>    height: 100%;</span></span>
<span class="line"><span>    position: absolute;</span></span>
<span class="line"><span>    background: #fff;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/2592f5973a6b42c494414cf42e3b6930~tplv-k3u1fbpfcp-watermark.image" alt="展开7.gif" loading="lazy"> 现在看看点击展开的效果吧</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/b2c68425dcf5453ca56ca573c76e470f~tplv-k3u1fbpfcp-watermark.image" alt="展开8.gif" loading="lazy"></p><p>现在展开以后，发现按钮不见（被刚才那个伪元素所覆盖，并且也点击不了），如果希望点击以后仍然可见呢？添加一下 <strong>:checked</strong> 状态即可，在展开时隐藏覆盖层</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.exp:checked+.text::after{</span></span>
<span class="line"><span>    visibility: hidden;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这样，就实现了在文字较少的情况下隐藏展开按钮的功能</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/031a3a50dfe74c4eaffa8bd9ce73c650~tplv-k3u1fbpfcp-watermark.image" alt="展开9.gif" loading="lazy"></p><p>最终完整代码可以查看<a href="https://link.juejin.cn/?target=https%3A%2F%2Fcodepen.io%2Fxboxyan%2Fpen%2FeYvNvYK%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://codepen.io/xboxyan/pen/eYvNvYK?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">codepen 多行展开收起自动隐藏</a>，兼容版本可以查看<a href="https://link.juejin.cn/?target=https%3A%2F%2Fcodepen.io%2Fxboxyan%2Fpen%2FLYWpWzK%3FfileGuid%3DXtpJhGpvWxj6qcTr" title="https://codepen.io/xboxyan/pen/LYWpWzK?fileGuid=XtpJhGpvWxj6qcTr" target="_blank" rel="noreferrer">codepen 多行展开收起自动隐藏（全兼容）</a></p><blockquote><p>需要注意的是，兼容版本可以支持到 <strong>IE 10+</strong>（这就过分了啊，居然还支持 IE），但是由于 IE 不支持 codepen，所以测试 IE 可以自行复制在本地测试。</p></blockquote><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/6f305e945be84abbbd3d79b460fd48ec~tplv-k3u1fbpfcp-watermark.image" alt="cc602bca-3538-466e-8dce-ee630ddd2635.gif" loading="lazy"></p><h1 id="四、总结和说明" tabindex="-1">四、总结和说明 <a class="header-anchor" href="#四、总结和说明" aria-label="Permalink to &quot;四、总结和说明&quot;">​</a></h1><p>总的来说，重点还是在<strong>布局方面</strong>，交互其实相对容易，整体实现的成本其实是很低的，也没有比较生僻的属性，除了布局方面 <strong>-webkit-box</strong> 貌似有点 bug （毕竟是 <strong>-webkit-内核</strong> ， 火狐只是借鉴了过来，难免有些问题），幸运的是可以通过另一种方式实现多行文本截断效果，兼容性相当不错，基本上全兼容（<strong>IE10+</strong>），这里整理一下实现重点</p><ul><li>文本环绕效果首先考虑<strong>浮动 float</strong></li><li><strong>flex 布局</strong>子元素可以通过百分比计算高度</li><li>多行文本截断还可以结合文本环绕效果用<strong>max-height</strong>模拟实现</li><li>状态切换可以借助 <strong>checkbox</strong></li><li>CSS 改变文本可以采用<strong>伪元素</strong>生成</li><li>多利用 CSS 遮挡 <strong>“障眼法”</strong></li></ul><p>多行文本展开收起效果可以说是业界一个<strong>老大难</strong>的问题了，有很多 js 解决方案，但是感觉都不是很完美，希望这个全新思路的 CSS 解决方式能给各位带来不一样的启发，感谢阅读，欢迎点赞、收藏、转发～</p>`,118)])])}const g=n(l,[["render",i]]);export{u as __pageData,g as default};
